import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S07/S07E07.html","title":"S07E07 The One with Ross's Library Book","lang":"zh-CN","frontmatter":{"title":"S07E07 The One with Ross's Library Book","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":153},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":33.05,"words":9914},"filePathRelative":"语言/英语/Friends老友记/S07/S07E07.md"}`),l={name:`S07E07.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-ross-s-library-book" tabindex="-1"><a class="header-anchor" href="#the-one-with-ross-s-library-book"><span>The One with Ross&#39;s Library Book</span></a></h1><blockquote><p><em>带罗斯图书馆书的那本</em></p></blockquote><p>The One With Ross’s Book</p><blockquote><p>拿罗斯书的那个</p></blockquote><p><strong>Written by: Scott Silveri</strong></p><blockquote><p>作者：斯科特·西尔维尼</p></blockquote><p><strong>Directed by: David Schwimmer</strong></p><blockquote><p>导演：大卫·施维默</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Joey and Rachel&#39;s, Joey is eating breakfast as Rachel enters having just woken up.</em></p><blockquote><p>🎬 <em>乔伊和瑞秋家，乔伊正在吃早餐，瑞秋刚醒来就进来了。</em></p></blockquote>`,13),r(p,{src:`/audio/friends/S07/S07E07/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[3]||=i(` Morning!`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`早上好！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/002.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`Rachel Green:`,-1),c[7]||=i(` Hi! Oh, how was your date last night?`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`嗨！哦，你昨晚的约会怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[11]||=i(` Pretty good.`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`很好。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Rachel Green:`,-1),c[15]||=i(` Oh good. (She walks to the closed bathroom door, opens it, and finds a naked woman wrapped in a towel.) Ahhh! My God, sorry! (She closes the door and confronts Joey.)`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`哦，很好。（她走向关着的浴室门，打开门，发现一个赤裸的女人裹着毛巾。）啊！天哪，对不起！（她关上门，面对乔伊。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/005.mp3`}),c[17]||=i(),c[18]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[19]||=i(` Okay, really good. Anyway I gotta go; I’m late for work.`,-1),c[20]||=a(`blockquote`,null,[a(`p`,null,`好的，真的很好。反正我得走了；我上班迟到了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/006.mp3`}),c[21]||=i(),c[22]||=a(`strong`,null,`Rachel Green:`,-1),c[23]||=i(` What-what?! You’re gonna leave this person with me?!`,-1),c[24]||=a(`blockquote`,null,[a(`p`,null,`什么？！你要把这个人留给我？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/007.mp3`}),c[25]||=i(),c[26]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[27]||=i(` Yeah—Hey, don’t worry, she’s a terrific girl. And hey listen, could you do me a favor? When she comes out could you just mention that I’m not looking for a serious relationship; that’d be great.`,-1),c[28]||=a(`blockquote`,null,[a(`p`,null,`是的，嘿，别担心，她是个很棒的女孩。嘿，听着，你能帮我个忙吗？当她出来的时候，你能不能说我不是在寻找一段严肃的关系；那太好了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/008.mp3`}),c[29]||=i(),c[30]||=a(`strong`,null,`Rachel Green:`,-1),c[31]||=i(` Why?! What?! Are you kidding?!`,-1),c[32]||=a(`blockquote`,null,[a(`p`,null,`为什么？！什么？！你在开玩笑吗？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/009.mp3`}),c[33]||=i(),c[34]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[35]||=i(` Just casually slip it in, y’know lay the groundwork. Tell her uh, I’m a loner—No! An outlaw! Tell her she doesn’t want to get mixed up with the likes of me.`,-1),c[36]||=a(`blockquote`,null,[a(`p`,null,`随便塞进去，你知道的，打好基础。告诉她我是个孤独的人不！一个歹徒！告诉她她不想和我这样的人混在一起。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/010.mp3`}),c[37]||=i(),c[38]||=a(`strong`,null,`Rachel Green:`,-1),c[39]||=i(` Y’know what? That’s a lot to remember, can’t I just tell her you’re a pig?`,-1),c[40]||=a(`blockquote`,null,[a(`p`,null,`你知道吗？要记住的太多了，我就不能告诉她你是头猪吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/011.mp3`}),c[41]||=i(),c[42]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[43]||=i(` Hey, I’m gonna call her later! Honest! Oh come on, Chandler used to do it! He’d even make the girl pancakes! Plus, he’d make extras and leave ‘em for me.`,-1),c[44]||=a(`blockquote`,null,[a(`p`,null,`嘿，我待会儿给她打电话！诚实的哦，得了吧，钱德勒以前是这么做的！他甚至会给女孩做煎饼！另外，他会做些额外的东西，留给我。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/012.mp3`}),c[45]||=i(),c[46]||=a(`strong`,null,`Rachel Green:`,-1),c[47]||=i(` Well forget it, I’m not telling that girl anything. That is not my responsibility.`,-1),c[48]||=a(`blockquote`,null,[a(`p`,null,`算了吧，我什么都没告诉那个女孩。这不是我的责任。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/013.mp3`}),c[49]||=i(),c[50]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[51]||=i(` Fine! (Pause) Now, where’d we land on those pancakes? (She chases him out the door as his date emerges from the bathroom.)`,-1),c[52]||=a(`blockquote`,null,[a(`p`,null,`很好！（停顿）现在，我们在哪里吃的煎饼？（当他的约会对象从浴室出来时，她把他赶出门。）`)],-1),c[53]||=a(`p`,null,`Joey’s Date: Hi!`,-1),c[54]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/014.mp3`}),c[55]||=i(),c[56]||=a(`strong`,null,`Rachel Green:`,-1),c[57]||=i(` Hi.`,-1),c[58]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),c[59]||=a(`p`,null,`Joey’s Date: Sorry about that, but I couldn’t get that lock to work on the door.`,-1),c[60]||=a(`blockquote`,null,[a(`p`,null,`很抱歉，我没法把门锁好。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/015.mp3`}),c[61]||=i(),c[62]||=a(`strong`,null,`Rachel Green:`,-1),c[63]||=i(` Yeah, Joey kinda disabled it when I moved in.`,-1),c[64]||=a(`blockquote`,null,[a(`p`,null,`是的，乔伊在我搬进来的时候把它弄坏了。`)],-1),c[65]||=a(`p`,null,`Joey’s Date: You must be Rachel, I’m Erin.`,-1),c[66]||=a(`blockquote`,null,[a(`p`,null,`你一定是瑞秋，我是艾琳。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/016.mp3`}),c[67]||=i(),c[68]||=a(`strong`,null,`Rachel Green:`,-1),c[69]||=i(` Hi.`,-1),c[70]||=a(`blockquote`,null,[a(`p`,null,`嗨。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/017.mp3`}),c[71]||=i(),c[72]||=a(`strong`,null,`Erin:`,-1),c[73]||=i(` Hi. I don’t mean this to sound like high school, but did he say anything about me?`,-1),c[74]||=a(`blockquote`,null,[a(`p`,null,`嗨。我的意思不是说这听起来像高中，但他有没有提到我？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/018.mp3`}),c[75]||=t(` <strong>Rachel Green:</strong> (pause) Would you like some pancakes?<blockquote><p>（停顿）你想要些煎饼吗？</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>N.Y.U’s University Library, Ross is entering with Chandler.</em></p><blockquote><p>🎬 <em>纽约大学图书馆，罗斯和钱德勒一起进入。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E07/019.mp3`}),c[76]||=i(),c[77]||=a(`strong`,null,`Chandler Bing:`,-1),c[78]||=i(` …Come on! Why are we here?!`,-1),c[79]||=a(`blockquote`,null,[a(`p`,null,`……来吧！我们为什么在这里？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/020.mp3`}),c[80]||=i(),c[81]||=a(`strong`,null,`Ross Geller:`,-1),c[82]||=i(` Okay, okay take a guess.`,-1),c[83]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，猜猜看。`)],-1),c[84]||=a(`p`,null,[a(`em`,null,`(An old woman pushes a cart full of books past.)`)],-1),c[85]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（一位老妇人推着一车书走过。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/021.mp3`}),c[86]||=i(),c[87]||=a(`strong`,null,`Chandler Bing:`,-1),c[88]||=i(` The hot chicks?`,-1),c[89]||=a(`blockquote`,null,[a(`p`,null,`辣妹？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/022.mp3`}),c[90]||=i(),c[91]||=a(`strong`,null,`Ross Geller:`,-1),c[92]||=i(` Okay, okay, I was typing names into the library computer earlier, y’know-y’know for fun, and I typed mine in and guess what came up? My doctoral dissertation! It’s here! Yeah, it’s right-it’s right down here! In the biggest library in the university! (They start heading that way, towards a secluded section behind the racks.)`,-1),c[93]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，我早些时候在图书馆的电脑上输入名字，你知道，你知道是为了好玩，我输入了我的名字，猜猜结果是什么？我的博士论文！就在这里！没错，就在这下面！在大学里最大的图书馆里！（他们开始往那边走，朝着货架后面一个隐蔽的区域走去。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/023.mp3`}),c[94]||=i(),c[95]||=a(`strong`,null,`Chandler Bing:`,-1),c[96]||=i(` Wow that’s actually pretty cool.`,-1),c[97]||=a(`blockquote`,null,[a(`p`,null,`哇，那真是太酷了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/024.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`Ross Geller:`,-1),c[100]||=i(` (stopping quickly) Oh umm, there’s also a book here by a woman named Wendy Bagina. (They both laugh, but stop when the hear moaning coming from the next aisle.) What is that?`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`（快速停下来）哦，嗯，这里还有一本书，是一位名叫温迪·巴吉娜的女士写的。（他们都笑了，但听到隔壁过道传来呻吟声，他们就停了下来。）那是什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/025.mp3`}),c[102]||=i(),c[103]||=a(`strong`,null,`Chandler Bing:`,-1),c[104]||=i(` Sounds like two people are really enjoying the Dewey decimal system.`,-1),c[105]||=a(`blockquote`,null,[a(`p`,null,`听起来好像有两个人很喜欢杜威十进制。`)],-1),c[106]||=a(`p`,null,[a(`em`,null,`(They go around the last row of bookshelves and find a couple doing what college coeds do in secluded corners of university libraries. For those of you who don’t know what I’m talking about, let’s just say that clothing is undone. Ross gasps and the couple gets up and runs away.)`)],-1),c[107]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们绕过最后一排书架，发现一对夫妇在大学图书馆的僻静角落里做着大学女生们做的事。对于那些不知道我在说什么的人，我们就说衣服没做了。罗斯喘息着，这对夫妇起身跑开了。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/026.mp3`}),c[108]||=i(),c[109]||=a(`strong`,null,`Female Student:`,-1),c[110]||=i(` (as they are moving past Ross) I’m so sorry!`,-1),c[111]||=a(`blockquote`,null,[a(`p`,null,`（当他们经过罗斯时）我很抱歉！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/027.mp3`}),c[112]||=i(),c[113]||=a(`strong`,null,`Male Student:`,-1),c[114]||=i(` Sorry!`,-1),c[115]||=a(`blockquote`,null,[a(`p`,null,`对不起！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/028.mp3`}),c[116]||=i(),c[117]||=a(`strong`,null,`Chandler Bing:`,-1),c[118]||=i(` You didn’t bring me here to do that, did you?`,-1),c[119]||=a(`blockquote`,null,[a(`p`,null,`你把我带到这里来不是为了这个，是吗？`)],-1),c[120]||=a(`hr`,null,null,-1),c[121]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica’s Restaurant Kitchen, Monica is cooking as a waitress enters carrying a plate of food that has been sent back.`)],-1),c[122]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡的餐厅厨房，莫妮卡正在做饭，一名女服务员端着一盘已经送回来的食物进来。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/029.mp3`}),c[123]||=i(),c[124]||=a(`strong`,null,`Monica Geller:`,-1),c[125]||=i(` She sent the chicken back again?!`,-1),c[126]||=a(`blockquote`,null,[a(`p`,null,`她又把鸡送回来了？！`)],-1),c[127]||=a(`p`,null,`The **Waitress: **She says it’s to dry now and she wants to come back here and explain to you exactly how she wants it.`,-1),c[128]||=a(`blockquote`,null,[a(`p`,null,`她说现在要晾干了，她想回到这里，向你解释她到底想要什么。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/030.mp3`}),c[129]||=i(),c[130]||=a(`strong`,null,`Monica Geller:`,-1),c[131]||=i(` Well fine! I want to meet this chicken expert! Send the Colonel in!`,-1),c[132]||=a(`blockquote`,null,[a(`p`,null,`很好！我想见见这位鸡肉专家！让上校进来！`)],-1),c[133]||=a(`p`,null,[a(`em`,null,`(The waitress lets her in as Monica is about to throw a lobster into a pot of boiling water (Although, she hasn’t taken off the rubber bands that hold the claws, so she can’t be that good of a chef). Anyway, guess who the Colonel is by the following phrase.)`)],-1),c[134]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡正要把一只龙虾扔进一壶沸水里，女服务员让她进来了（尽管她还没有脱下固定爪子的橡皮筋，所以她不可能是一个好厨师）。总之，用下面的短语猜猜上校是谁。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/031.mp3`}),c[135]||=i(),c[136]||=a(`strong`,null,`The Colonel:`,-1),c[137]||=i(` OH…MY…GAWD!!!! (Yep, it’s Janice.)`,-1),c[138]||=a(`blockquote`,null,[a(`p`,null,`哦……我的……天哪！！！！（是的，我是珍妮丝。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/032.mp3`}),c[139]||=i(),c[140]||=a(`strong`,null,`Monica Geller:`,-1),c[141]||=i(` (to the lobster) Lucky bastard! (Throws the lobster in and turns around to face the planet’s most annoying woman, next to Dr. Laura and Kathy Lee Gifford of course. She’s the most annoying female TV character however.) Janice.`,-1),c[142]||=a(`blockquote`,null,[a(`p`,null,`（对龙虾）幸运的混蛋！（把龙虾扔进去，转过身去面对这个星球上最令人讨厌的女人，当然仅次于劳拉博士和凯西·李·吉福德。然而，她是最令人讨厌的电视女角色。）珍妮丝。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/033.mp3`}),c[143]||=i(),c[144]||=a(`strong`,null,`Janice:`,-1),c[145]||=i(` How are you Ms. Hot Shot chef with the big fancy restaurant with the best chicken ever! (Does the laugh.)`,-1),c[146]||=a(`blockquote`,null,[a(`p`,null,`你好，这家有史以来最好鸡肉的豪华餐厅的大厨小姐！（观众笑了。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/034.mp3`}),c[147]||=i(),c[148]||=a(`strong`,null,`Monica Geller:`,-1),c[149]||=i(` I’m fine.`,-1),c[150]||=a(`blockquote`,null,[a(`p`,null,`我很好。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/035.mp3`}),c[151]||=i(),c[152]||=a(`strong`,null,`Janice:`,-1),c[153]||=i(` (notices Monica’s engagement ring) Ohh! What is that on your finger?! I’m blind!`,-1),c[154]||=a(`blockquote`,null,[a(`p`,null,`（注意到莫妮卡的订婚戒指）哦！你手指上是什么？！我瞎了！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/036.mp3`}),c[155]||=i(),c[156]||=a(`strong`,null,`Monica Geller:`,-1),c[157]||=i(` Oh… Uh…`,-1),c[158]||=a(`blockquote`,null,[a(`p`,null,`哦……嗯…`)],-1),r(p,{src:`/audio/friends/S07/S07E07/037.mp3`}),c[159]||=i(),c[160]||=a(`strong`,null,`Janice:`,-1),c[161]||=i(` So, who’s the lucky guy?`,-1),c[162]||=a(`blockquote`,null,[a(`p`,null,`那么，谁是幸运儿？`)],-1),c[163]||=a(`p`,null,`[Cut to Monica and Chandler’s just after Monica has finished telling Chandler what happened.]`,-1),c[164]||=a(`blockquote`,null,[a(`p`,null,`[在莫妮卡告诉钱德勒发生了什么之后，转到莫妮卡和钱德勒那里。]`)],-1),r(p,{src:`/audio/friends/S07/S07E07/038.mp3`}),c[165]||=i(),c[166]||=a(`strong`,null,`Chandler Bing:`,-1),c[167]||=i(` OH…MY…GAWD! I am so sorry sweetie, are you okay? You didn’t tell her we were getting married, did you?`,-1),c[168]||=a(`blockquote`,null,[a(`p`,null,`哦……我的……天哪！我很抱歉，亲爱的，你没事吧？你没告诉她我们要结婚，是吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/039.mp3`}),c[169]||=i(),c[170]||=a(`strong`,null,`Monica Geller:`,-1),c[171]||=i(` Well, she saw the ring.`,-1),c[172]||=a(`blockquote`,null,[a(`p`,null,`嗯，她看到了戒指。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/040.mp3`}),c[173]||=i(),c[174]||=a(`strong`,null,`Chandler Bing:`,-1),c[175]||=i(` Did she freak out?`,-1),c[176]||=a(`blockquote`,null,[a(`p`,null,`她疯了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/041.mp3`}),c[177]||=i(),c[178]||=a(`strong`,null,`Monica Geller:`,-1),c[179]||=i(` Well, she was shocked when I told her, but then again so were most people.`,-1),c[180]||=a(`blockquote`,null,[a(`p`,null,`我告诉她时，她很震惊，但大多数人也是。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/042.mp3`}),c[181]||=i(),c[182]||=a(`strong`,null,`Chandler Bing:`,-1),c[183]||=i(` Right.`,-1),c[184]||=a(`blockquote`,null,[a(`p`,null,`对。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/043.mp3`}),c[185]||=i(),c[186]||=a(`strong`,null,`Monica Geller:`,-1),c[187]||=i(` Well, she actually has a boyfriend y’know herself, named Clark. Uh, she also kinda invited herself to our wedding. Clark too.`,-1),c[188]||=a(`blockquote`,null,[a(`p`,null,`嗯，她实际上有一个你认识的男朋友，叫克拉克。她还邀请自己参加我们的婚礼。克拉克也是。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/044.mp3`}),c[189]||=i(),c[190]||=a(`strong`,null,`Chandler Bing:`,-1),c[191]||=i(` (laughs) You said no right?`,-1),c[192]||=a(`blockquote`,null,[a(`p`,null,`（笑）你说不，对吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/045.mp3`}),c[193]||=i(),c[194]||=a(`strong`,null,`Monica Geller:`,-1),c[195]||=i(` Huh?`,-1),c[196]||=a(`blockquote`,null,[a(`p`,null,`嗯？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/046.mp3`}),c[197]||=i(),c[198]||=a(`strong`,null,`Chandler Bing:`,-1),c[199]||=i(` You said no right?!`,-1),c[200]||=a(`blockquote`,null,[a(`p`,null,`你说不，对吧？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/047.mp3`}),c[201]||=i(),c[202]||=a(`strong`,null,`Monica Geller:`,-1),c[203]||=i(` Well, she corned me! She asked if the wedding was in town! I mean, what was I supposed to do?!`,-1),c[204]||=a(`blockquote`,null,[a(`p`,null,`嗯，她骗了我！她问婚礼是否在城里举行！我是说，我该怎么办？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/048.mp3`}),c[205]||=i(),c[206]||=a(`strong`,null,`Chandler Bing:`,-1),c[207]||=i(` Lie!!! How hard is that?! The check’s in the mail! Oh your baby is so cute! I can’t wait to read your book Ross!!`,-1),c[208]||=a(`blockquote`,null,[a(`p`,null,`撒谎！！！这有多难？！支票在邮寄中！哦，你的宝宝真可爱！我等不及要看你的书了，罗斯！！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/049.mp3`}),c[209]||=i(),c[210]||=a(`strong`,null,`Monica Geller:`,-1),c[211]||=i(` Come on! So she comes to the wedding! I mean it won’t be so bad.`,-1),c[212]||=a(`blockquote`,null,[a(`p`,null,`来吧！所以她来参加婚礼了！我的意思是不会那么糟糕。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/050.mp3`}),c[213]||=i(),c[214]||=a(`strong`,null,`Chandler Bing:`,-1),c[215]||=i(` What do you think she’s just gonna sit there quietly? You don’t think she’s gonna want to make a toast? You don’t think she’s gonna want to grab the microphone and sing Part-time Lover?!`,-1),c[216]||=a(`blockquote`,null,[a(`p`,null,`你觉得她会静静地坐在那里吗？你不认为她会想干杯吗？你不认为她会想抓住麦克风唱兼职情人？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/051.mp3`}),c[217]||=i(),c[218]||=a(`strong`,null,`Monica Geller:`,-1),c[219]||=i(` Oh my God, she’s not gonna like the chicken that night either is she?!`,-1),c[220]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天，她也不会喜欢那晚的鸡的，是吗？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/052.mp3`}),c[221]||=i(),c[222]||=a(`strong`,null,`Chandler Bing:`,-1),c[223]||=i(` Y’know what? It’s gonna be okay. Y’know what? She’s probably not gonna even want to come.`,-1),c[224]||=a(`blockquote`,null,[a(`p`,null,`你知道吗？不会有事的。你知道吗？她可能根本不想来。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/053.mp3`}),c[225]||=i(),c[226]||=a(`strong`,null,`Monica Geller:`,-1),c[227]||=i(` Really?`,-1),c[228]||=a(`blockquote`,null,[a(`p`,null,`真的吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/054.mp3`}),c[229]||=i(),c[230]||=a(`strong`,null,`Chandler Bing:`,-1),c[231]||=i(` No! That was a lie! See how easy that was?`,-1),c[232]||=a(`blockquote`,null,[a(`p`,null,`不！那是个谎言！看看这有多容易？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/055.mp3`}),c[233]||=i(),c[234]||=a(`strong`,null,`Monica Geller:`,-1),c[235]||=i(` So-so you would’ve just lied?`,-1),c[236]||=a(`blockquote`,null,[a(`p`,null,`那你就撒谎了？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/056.mp3`}),c[237]||=i(),c[238]||=a(`strong`,null,`Chandler Bing:`,-1),c[239]||=i(` Yes!!`,-1),c[240]||=a(`blockquote`,null,[a(`p`,null,`是的！！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/057.mp3`}),c[241]||=i(),c[242]||=a(`strong`,null,`Monica Geller:`,-1),c[243]||=i(` Would it really have been that easy?`,-1),c[244]||=a(`blockquote`,null,[a(`p`,null,`真的那么容易吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/058.mp3`}),c[245]||=i(),c[246]||=a(`strong`,null,`Chandler Bing:`,-1),c[247]||=i(` Yes!!!`,-1),c[248]||=a(`blockquote`,null,[a(`p`,null,`是的！！！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/059.mp3`}),c[249]||=i(),c[250]||=a(`strong`,null,`Monica Geller:`,-1),c[251]||=i(` Good, so do it Saturday night because we’re going to dinner with her and Clark.`,-1),c[252]||=a(`blockquote`,null,[a(`p`,null,`好的，周六晚上去吧，因为我们要和她和克拉克一起吃晚饭。`)],-1),c[253]||=a(`hr`,null,null,-1),c[254]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey and Rachel's, Joey is coming back from work to find Phoebe, Rachel, and someone else with her back turned is there.`)],-1),c[255]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊和瑞秋家，乔伊下班回来找菲比、瑞秋和另一个背朝下的人在那里。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/060.mp3`}),c[256]||=i(),c[257]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[258]||=i(` Hey! What’s up?`,-1),c[259]||=a(`blockquote`,null,[a(`p`,null,`嘿！怎么了？`)],-1),c[260]||=a(`p`,null,`Phoebe and **Rachel Green: **Hey!`,-1),c[261]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比和`),a(`strong`,null,`瑞秋·格林：`),i(`嘿！`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/061.mp3`}),c[262]||=i(),c[263]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[264]||=i(` Hey-hey, who’s your friend? (Erin turns around to face Joey, startling him) Hey!!`,-1),c[265]||=a(`blockquote`,null,[a(`p`,null,`嘿，谁是你的朋友？（艾琳转身面对乔伊，吓了他一跳）嘿！！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/062.mp3`}),c[266]||=i(),c[267]||=a(`strong`,null,`Erin:`,-1),c[268]||=i(` Hey Joey!`,-1),c[269]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔伊！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/063.mp3`}),c[270]||=i(),c[271]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[272]||=i(` Erin! Still here!`,-1),c[273]||=a(`blockquote`,null,[a(`p`,null,`艾琳！还在这里！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/064.mp3`}),c[274]||=i(),c[275]||=a(`strong`,null,`Rachel Green:`,-1),c[276]||=i(` Yeah, we ended up spending the day together and had such a great time!`,-1),c[277]||=a(`blockquote`,null,[a(`p`,null,`是啊，我们最后在一起度过了一天，玩得很开心！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/065.mp3`}),c[278]||=i(),c[279]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[280]||=i(` Why wouldn’t ya? Erin is great! Then-then there’s you guys.`,-1),c[281]||=a(`blockquote`,null,[a(`p`,null,`你为什么不呢？艾琳很棒！然后就是你们了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/066.mp3`}),c[282]||=i(),c[283]||=a(`strong`,null,`Erin:`,-1),c[284]||=i(` Ohh, listen. I’ve got to get going. Today was great, thanks!`,-1),c[285]||=a(`blockquote`,null,[a(`p`,null,`哦，听着。我得走了。今天很棒，谢谢！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/067.mp3`}),c[286]||=i(),c[287]||=a(`strong`,null,`Rachel Green:`,-1),c[288]||=i(` I know!`,-1),c[289]||=a(`blockquote`,null,[a(`p`,null,`我知道！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/068.mp3`}),c[290]||=i(),c[291]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[292]||=i(` Okay!`,-1),c[293]||=a(`blockquote`,null,[a(`p`,null,`好的！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/069.mp3`}),c[294]||=i(),c[295]||=a(`strong`,null,`Erin:`,-1),c[296]||=i(` Bye Joey. (Kisses him.) Last night was fun.`,-1),c[297]||=a(`blockquote`,null,[a(`p`,null,`再见，乔伊。（吻他）昨晚很有趣。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/070.mp3`}),c[298]||=i(),c[299]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[300]||=i(` Yeah. I’ll uh, I’ll call ya.`,-1),c[301]||=a(`blockquote`,null,[a(`p`,null,`是的。我会给你打电话。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/071.mp3`}),c[302]||=i(),c[303]||=a(`strong`,null,`Rachel Green:`,-1),c[304]||=i(` Oh and I’ll call ya too!`,-1),c[305]||=a(`blockquote`,null,[a(`p`,null,`哦，我也会打电话给你的！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/072.mp3`}),c[306]||=i(),c[307]||=a(`strong`,null,`Erin:`,-1),c[308]||=i(` Or I’ll call you!`,-1),c[309]||=a(`blockquote`,null,[a(`p`,null,`不然我就打电话给你！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/073.mp3`}),c[310]||=i(),c[311]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[312]||=i(` And call me!`,-1),c[313]||=a(`blockquote`,null,[a(`p`,null,`给我打电话！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/074.mp3`}),c[314]||=i(),c[315]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[316]||=i(` (to Erin) Okay, good to see you again.`,-1),c[317]||=a(`blockquote`,null,[a(`p`,null,`（对艾琳）好的，很高兴再次见到你。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/075.mp3`}),c[318]||=i(),c[319]||=a(`strong`,null,`Erin:`,-1),c[320]||=i(` Bye.`,-1),c[321]||=a(`blockquote`,null,[a(`p`,null,`再见。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/076.mp3`}),c[322]||=i(),c[323]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[324]||=i(` Bye-bye.`,-1),c[325]||=a(`blockquote`,null,[a(`p`,null,`再见。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/077.mp3`}),c[326]||=i(),c[327]||=a(`strong`,null,`Rachel Green:`,-1),c[328]||=i(` Bye!`,-1),c[329]||=a(`blockquote`,null,[a(`p`,null,`再见！`)],-1),c[330]||=a(`p`,null,[a(`em`,null,`(Joey closes the door behind her.)`)],-1),c[331]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊关上了身后的门。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/078.mp3`}),c[332]||=i(),c[333]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[334]||=i(` So, system kinda broke down huh?!`,-1),c[335]||=a(`blockquote`,null,[a(`p`,null,`所以，系统有点崩溃了，嗯？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/079.mp3`}),c[336]||=i(),c[337]||=a(`strong`,null,`Rachel Green:`,-1),c[338]||=i(` Oh Joey, I’m sorry I just couldn’t tell her all those things you wanted me to tell her. And y’know we got to talking and I…`,-1),c[339]||=a(`blockquote`,null,[a(`p`,null,`哦，乔伊，很抱歉我不能告诉她所有你想让我告诉她的事情。你知道我们得谈谈我…`)],-1),r(p,{src:`/audio/friends/S07/S07E07/080.mp3`}),c[340]||=i(),c[341]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[342]||=i(` We want you to marry her!`,-1),c[343]||=a(`blockquote`,null,[a(`p`,null,`我们要你嫁给她！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/081.mp3`}),c[344]||=i(),c[345]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[346]||=i(` What?!!`,-1),c[347]||=a(`blockquote`,null,[a(`p`,null,`什么？！！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/082.mp3`}),c[348]||=i(),c[349]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[350]||=i(` She is so amazing! You have no idea.`,-1),c[351]||=a(`blockquote`,null,[a(`p`,null,`她太棒了！你不知道。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/083.mp3`}),c[352]||=i(),c[353]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[354]||=i(` No idea? Who do you think brought her here?`,-1),c[355]||=a(`blockquote`,null,[a(`p`,null,`不知道？你认为是谁把她带到这里来的？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/084.mp3`}),c[356]||=i(),c[357]||=a(`strong`,null,`Rachel Green:`,-1),c[358]||=i(` Cupid.`,-1),c[359]||=a(`blockquote`,null,[a(`p`,null,`丘比特。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/085.mp3`}),c[360]||=i(),c[361]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[362]||=i(` Joey, she’s so cool. She speaks four languages.`,-1),c[363]||=a(`blockquote`,null,[a(`p`,null,`乔伊，她太酷了。她会说四种语言。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/086.mp3`}),c[364]||=i(),c[365]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[366]||=i(` Man, do you know what guys want!`,-1),c[367]||=a(`blockquote`,null,[a(`p`,null,`伙计，你知道男人想要什么吗！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/087.mp3`}),c[368]||=i(),c[369]||=a(`strong`,null,`Rachel Green:`,-1),c[370]||=i(` Look Joey, come on she’s so perfect for you! I mean she’s sweet, she-she likes baseball, and she-she had two beers at lunch.`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`听着，乔伊，别这样，她真是太适合你了！我是说她很可爱，她喜欢棒球，午餐时喝了两杯啤酒。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/088.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[374]||=i(` My beers?! Look you guys, she’s a very nice girl. Okay? We had a good time, but I just—I don’t see it going anywhere.`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`我的啤酒？！你们看，她是个很好的女孩。可以我们玩得很开心，但我只是，我看它哪儿也去不了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/089.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[378]||=i(` Yeah, but you always say that.`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`是啊，但你总是这么说。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/090.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`Rachel Green:`,-1),c[382]||=i(` Yeah, maybe if you gave this girl a chance it would go somewhere.`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`是啊，也许如果你给这个女孩一个机会，它会去某个地方。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/091.mp3`}),c[384]||=i(),c[385]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[386]||=i(` Look I’m sorry you guys, I-I just don’t think so.`,-1),c[387]||=a(`blockquote`,null,[a(`p`,null,`听着，我很抱歉你们，我只是不这么认为。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/092.mp3`}),c[388]||=i(),c[389]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[390]||=i(` Whatever.`,-1),c[391]||=a(`blockquote`,null,[a(`p`,null,`不管怎样。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/093.mp3`}),c[392]||=i(),c[393]||=a(`strong`,null,`Rachel Green:`,-1),c[394]||=i(` Fine. (They start to walk away.)`,-1),c[395]||=a(`blockquote`,null,[a(`p`,null,`好的。（他们开始走开。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/094.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[398]||=i(` Hey, don’t start judging me! (To Rachel) Huh? You’re the one who’s in love with her assistant! (To Phoebe) Huh? And you, you’re the one having the affair with the guy who keeps the pigeons on the roof!`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`嘿，别开始评判我！（对瑞秋）嗯？是你爱上了她的助手！（对菲比）嗯？而你，你就是那个和屋顶上养鸽子的家伙有暧昧关系的人！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/095.mp3`}),c[400]||=i(),c[401]||=a(`strong`,null,`Rachel Green:`,-1),c[402]||=i(` Phoebe!`,-1),c[403]||=a(`blockquote`,null,[a(`p`,null,`菲比！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/096.mp3`}),c[404]||=i(),c[405]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[406]||=i(` Secret affair!`,-1),c[407]||=a(`blockquote`,null,[a(`p`,null,`秘密事件！`)],-1),c[408]||=a(`hr`,null,null,-1),c[409]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Rachel and Joey are there as Ross enters.`)],-1),c[410]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯进来时，中央公园、瑞秋和乔伊在那里。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/097.mp3`}),c[411]||=i(),c[412]||=a(`strong`,null,`Ross Geller:`,-1),c[413]||=i(` People are doing it in front of my book!`,-1),c[414]||=a(`blockquote`,null,[a(`p`,null,`人们都在我的书前做这件事！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/098.mp3`}),c[415]||=i(),c[416]||=a(`strong`,null,`Rachel Green:`,-1),c[417]||=i(` I’m sorry?`,-1),c[418]||=a(`blockquote`,null,[a(`p`,null,`对不起？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/099.mp3`}),c[419]||=i(),c[420]||=a(`strong`,null,`Ross Geller:`,-1),c[421]||=i(` My doctoral dissertation is in the library at school, I went to see it, and there were students makin’ babies right in the middle of the Paleontology section!`,-1),c[422]||=a(`blockquote`,null,[a(`p`,null,`我的博士论文在学校的图书馆里，我去看了，有学生在古生物学部分的中间生孩子。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/100.mp3`}),c[423]||=i(),c[424]||=a(`strong`,null,`Rachel Green:`,-1),c[425]||=i(` Oh my God! Did you get to see anything good?`,-1),c[426]||=a(`blockquote`,null,[a(`p`,null,`我的天啊！你看到什么好东西了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/101.mp3`}),c[427]||=i(),c[428]||=a(`strong`,null,`Ross Geller:`,-1),c[429]||=i(` Let me ask you something, at your school was there a like uh a place on campus where students went to uh, fool around.`,-1),c[430]||=a(`blockquote`,null,[a(`p`,null,`让我问你一件事，在你的学校里，有一个像校园里的一个地方，学生们去，呃，胡闹。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/102.mp3`}),c[431]||=i(),c[432]||=a(`strong`,null,`Rachel Green:`,-1),c[433]||=i(` Yeah, there was. It was—there the corner of the library where-where all these dusty books that nobody ever read—Yes, there was.`,-1),c[434]||=a(`blockquote`,null,[a(`p`,null,`是的，有。就在图书馆的一角，那里有很多没人读过的满是灰尘的书。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/103.mp3`}),c[435]||=i(),c[436]||=a(`strong`,null,`Ross Geller:`,-1),c[437]||=i(` Great! Because people kept showing up, I think it’s like uh-a thing!`,-1),c[438]||=a(`blockquote`,null,[a(`p`,null,`太好了！因为人们不断出现，我想这就像是一件事！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/104.mp3`}),c[439]||=i(),c[440]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[441]||=i(` Now hold on a second, fifth floor against that back wall?`,-1),c[442]||=a(`blockquote`,null,[a(`p`,null,`现在在第二层、第五层靠着后墙等着？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/105.mp3`}),c[443]||=i(),c[444]||=a(`strong`,null,`Ross Geller:`,-1),c[445]||=i(` Oh for cryin’ out loud! (He storms out.)`,-1),c[446]||=a(`blockquote`,null,[a(`p`,null,`噢，为了大声哭！（他怒气冲冲地走了出去。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/106.mp3`}),c[447]||=i(),c[448]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[449]||=i(` All right, so we should go catch our movie.`,-1),c[450]||=a(`blockquote`,null,[a(`p`,null,`好吧，我们应该去看电影了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/107.mp3`}),c[451]||=i(),c[452]||=a(`strong`,null,`Rachel Green:`,-1),c[453]||=i(` Well now what’s the rush?`,-1),c[454]||=a(`blockquote`,null,[a(`p`,null,`那么现在急什么呢？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/108.mp3`}),c[455]||=i(),c[456]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[457]||=i(` I like to see the previews. (Rachel looks at him.) The candy.`,-1),c[458]||=a(`blockquote`,null,[a(`p`,null,`我喜欢看预告片。（瑞秋看着他）糖果。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/109.mp3`}),c[459]||=i(),c[460]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[461]||=i(` (entering with Erin) Oh. Hey!`,-1),c[462]||=a(`blockquote`,null,[a(`p`,null,`（和艾琳一起进来）哦。嘿`)],-1),r(p,{src:`/audio/friends/S07/S07E07/110.mp3`}),c[463]||=i(),c[464]||=a(`strong`,null,`Rachel Green:`,-1),c[465]||=i(` Well look who’s here!`,-1),c[466]||=a(`blockquote`,null,[a(`p`,null,`看谁来了！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/111.mp3`}),c[467]||=i(),c[468]||=a(`strong`,null,`Erin:`,-1),c[469]||=i(` Hey!`,-1),c[470]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/112.mp3`}),c[471]||=i(),c[472]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[473]||=i(` Hey!`,-1),c[474]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/113.mp3`}),c[475]||=i(),c[476]||=a(`strong`,null,`Erin:`,-1),c[477]||=i(` Joey.`,-1),c[478]||=a(`blockquote`,null,[a(`p`,null,`乔伊。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/114.mp3`}),c[479]||=i(),c[480]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[481]||=i(` Erin.`,-1),c[482]||=a(`blockquote`,null,[a(`p`,null,`艾琳。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/115.mp3`}),c[483]||=i(),c[484]||=a(`strong`,null,`Erin:`,-1),c[485]||=i(` Hey Rachel.`,-1),c[486]||=a(`blockquote`,null,[a(`p`,null,`嘿，瑞秋。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/116.mp3`}),c[487]||=i(),c[488]||=a(`strong`,null,`Rachel Green:`,-1),c[489]||=i(` Hi! Well, we were just about to take off and see a movie. Oh no!`,-1),c[490]||=a(`blockquote`,null,[a(`p`,null,`嗨！我们正要出发去看电影。哦，不！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/117.mp3`}),c[491]||=i(),c[492]||=a(`strong`,null,`Erin:`,-1),c[493]||=i(` What’s wrong?`,-1),c[494]||=a(`blockquote`,null,[a(`p`,null,`怎么了？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/118.mp3`}),c[495]||=i(),c[496]||=a(`strong`,null,`Rachel Green:`,-1),c[497]||=i(` Oh Phoebe, we forgot that party we have to go to.`,-1),c[498]||=a(`blockquote`,null,[a(`p`,null,`哦，菲比，我们忘了我们要去的那个聚会了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/119.mp3`}),c[499]||=i(),c[500]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[501]||=i(` Oh no.`,-1),c[502]||=a(`blockquote`,null,[a(`p`,null,`哦，不。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/120.mp3`}),c[503]||=i(),c[504]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[505]||=i(` (skeptical) What party?`,-1),c[506]||=a(`blockquote`,null,[a(`p`,null,`（怀疑）什么派对？`)],-1),c[507]||=a(`p`,null,`Phoebe and **Rachel Green: **A birthday party.`,-1),c[508]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比和`),a(`strong`,null,`瑞秋·格林：`),i(`生日派对。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/121.mp3`}),c[509]||=i(),c[510]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[511]||=i(` Who’s birthday party?`,-1),c[512]||=a(`blockquote`,null,[a(`p`,null,`谁的生日派对？`)],-1),c[513]||=a(`p`,null,`Phoebe and **Rachel Green: **Allison’s birthday party.`,-1),c[514]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比和`),a(`strong`,null,`瑞秋·格林：`),i(`艾莉森的生日派对。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/122.mp3`}),c[515]||=i(),c[516]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[517]||=i(` (still skeptical) Oh, and how is Allison?`,-1),c[518]||=a(`blockquote`,null,[a(`p`,null,`（仍然怀疑）哦，艾莉森怎么样？`)],-1),c[519]||=a(`p`,null,`Phoebe and **Rachel Green: **32. (Joey’s not buying it.)`,-1),c[520]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比和`),a(`strong`,null,`瑞秋·格林：`),i(`32。（乔伊才不信呢。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/123.mp3`}),c[521]||=i(),c[522]||=a(`strong`,null,`Rachel Green:`,-1),c[523]||=i(` (does a retching sound) Wait a minute! Why don’t you guys do something?!`,-1),c[524]||=a(`blockquote`,null,[a(`p`,null,`（发出干呕声）等一下！你们为什么不做点什么？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/124.mp3`}),c[525]||=t(` <strong>Joey Tribbiani:</strong> (still skeptical) Yeah, look how that worked out.<blockquote><p>（仍然怀疑）是的，看看结果如何。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>The Library, Ross enters and heads to the desk to talk to the male librarian on duty.</em></p><blockquote><p>🎬 <em>图书馆，罗斯走进来，走向书桌，与当班的男图书管理员交谈。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E07/125.mp3`}),c[526]||=i(),c[527]||=a(`strong`,null,`Ross Geller:`,-1),c[528]||=i(` Excuse me. Hi, I’m a professor here. Do you know the Paleontology section, fifth floor, stack 437?`,-1),c[529]||=a(`blockquote`,null,[a(`p`,null,`对不起。嗨，我是这里的教授。你知道437号堆栈五楼的古生物学部分吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/126.mp3`}),c[530]||=i(),c[531]||=a(`strong`,null,`The Librarian:`,-1),c[532]||=i(` Well, yes! Just give me five minutes, I just have to find someone to cover my shift.`,-1),c[533]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的！给我五分钟，我得找个人替我值班。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/127.mp3`}),c[534]||=i(),c[535]||=a(`strong`,null,`Ross Geller:`,-1),c[536]||=i(` No! No!! No! Can I speak to someone in charge please?! (The librarian brings his boss over.)`,-1),c[537]||=a(`blockquote`,null,[a(`p`,null,`不！不不我能和负责人说话吗？！（图书管理员把他的老板带过来。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/128.mp3`}),c[538]||=i(),c[539]||=a(`strong`,null,`The Head Librarian:`,-1),c[540]||=i(` How can I help you?`,-1),c[541]||=a(`blockquote`,null,[a(`p`,null,`我能为您做些什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/129.mp3`}),c[542]||=i(),c[543]||=a(`strong`,null,`Ross Geller:`,-1),c[544]||=i(` Hi, I was wondering if it is possible to increase security in the Paleontology section? See I-I wrote a book up there and instead of reading it people are-are-are well, rolling around in front of it.`,-1),c[545]||=a(`blockquote`,null,[a(`p`,null,`嗨，我想知道是否有可能增加古生物学部分的安全性？我在上面写了一本书，人们并没有读它，而是在它面前转来转去。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/130.mp3`}),c[546]||=i(),c[547]||=a(`strong`,null,`The Head Librarian:`,-1),c[548]||=i(` We are aware of the problem you are referring too. (He turns to look at the previous librarian.) But as far as increasing security, I’m afraid the library is very understaffed. I, I can’t help you.`,-1),c[549]||=a(`blockquote`,null,[a(`p`,null,`我们也知道你提到的问题。（他回头看了看前一位图书馆员。）但就加强安全而言，恐怕图书馆人手不足。一、 我帮不了你。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/131.mp3`}),c[550]||=i(),c[551]||=a(`strong`,null,`Ross Geller:`,-1),c[552]||=i(` Well, fine. Fine! If-if I’m the only person with any appreciation of the sanctity of the written word, I’ll go up there and defend it myself! (Starts to do so, but stops and to the previous librarian) And don’t you follow me!`,-1),c[553]||=a(`blockquote`,null,[a(`p`,null,`嗯，很好。好的如果我是唯一一个欣赏文字神圣性的人，我会亲自去捍卫它！（开始这样做，但停了下来，对前一位图书管理员说）别跟着我！`)],-1),c[554]||=a(`hr`,null,null,-1),c[555]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey and Rachel's, Rachel and Phoebe are doing dishes as Joey enters.`)],-1),c[556]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊和瑞秋家，瑞秋和菲比正在洗碗，乔伊进来。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/132.mp3`}),c[557]||=i(),c[558]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[559]||=i(` Hey.`,-1),c[560]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/133.mp3`}),c[561]||=i(),c[562]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[563]||=i(` Hey!`,-1),c[564]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/134.mp3`}),c[565]||=i(),c[566]||=a(`strong`,null,`Rachel Green:`,-1),c[567]||=i(` How did it go with Erin?`,-1),c[568]||=a(`blockquote`,null,[a(`p`,null,`艾琳怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/135.mp3`}),c[569]||=i(),c[570]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[571]||=i(` Oh, unbelievable! We had the best time!`,-1),c[572]||=a(`blockquote`,null,[a(`p`,null,`哦，难以置信！我们玩得很开心！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/136.mp3`}),c[573]||=i(),c[574]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[575]||=i(` Yay!! Oh so, you’re not, you’re not mad at us anymore?`,-1),c[576]||=a(`blockquote`,null,[a(`p`,null,`耶！！哦，那么，你不是，你不再生我们的气了？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/137.mp3`}),c[577]||=i(),c[578]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[579]||=i(` No! No! No! You guys were totally right! This is so much better than the first time we went out. Y’know? That was so awkward, we were really nervous.`,-1),c[580]||=a(`blockquote`,null,[a(`p`,null,`不！不不你们完全正确！这比我们第一次出去要好得多。你知道吗？那太尴尬了，我们真的很紧张。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/138.mp3`}),c[581]||=i(),c[582]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[583]||=i(` Didn’t you sleep together?`,-1),c[584]||=a(`blockquote`,null,[a(`p`,null,`你没睡在一起吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/139.mp3`}),c[585]||=i(),c[586]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[587]||=i(` Yeah that really calms me down. And! We have so much in common! She loves sandwiches, sports, although she is a Met fan, not much of an issue now but if were ever to have kids, well that’s a…`,-1),c[588]||=a(`blockquote`,null,[a(`p`,null,`是的，这真的让我平静下来。还有！我们有很多共同点！她喜欢三明治，运动，虽然她是一个大都会迷，现在不是什么大问题，但如果我们有孩子，那是一个…`)],-1),r(p,{src:`/audio/friends/S07/S07E07/140.mp3`}),c[589]||=i(),c[590]||=a(`strong`,null,`Rachel Green:`,-1),c[591]||=i(` (gasps) Oh my God! Listen to you talkin’ about having kids. Oh my Joey. (She goes over and hugs him.) Oh, please don’t get married before I do.`,-1),c[592]||=a(`blockquote`,null,[a(`p`,null,`（喘息）哦，我的天啊！听你说要孩子。哦，我的乔伊。（她走过去拥抱他）哦，请不要在我结婚之前就结婚。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/141.mp3`}),c[593]||=i(),c[594]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[595]||=i(` Okay.`,-1),c[596]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),c[597]||=a(`hr`,null,null,-1),c[598]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`A Restaurant, Monica and Chandler are on their date with Janice and Clark, however Clark is a no show and Janice is crying the Mississippi River about it.`)],-1),c[599]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`一家餐厅，莫妮卡和钱德勒正在与珍妮丝和克拉克约会，但克拉克不在，珍妮丝为此哭泣密西西比河。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/142.mp3`}),c[600]||=i(),c[601]||=a(`strong`,null,`Janice:`,-1),c[602]||=i(` Oh. Oh I just cannot believe Clark stood me up!`,-1),c[603]||=a(`blockquote`,null,[a(`p`,null,`哦。我真不敢相信克拉克竟然放我鸽子！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/143.mp3`}),c[604]||=i(),c[605]||=a(`strong`,null,`Monica Geller:`,-1),c[606]||=i(` He might still show up.`,-1),c[607]||=a(`blockquote`,null,[a(`p`,null,`他可能还会出现。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/144.mp3`}),c[608]||=i(),c[609]||=a(`strong`,null,`Janice:`,-1),c[610]||=i(` Oh, what are you, stupid? It’s been three hours.`,-1),c[611]||=a(`blockquote`,null,[a(`p`,null,`哦，你是什么，笨蛋？已经三个小时了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/145.mp3`}),c[612]||=i(),c[613]||=a(`strong`,null,`Monica Geller:`,-1),c[614]||=i(` Is that all?`,-1),c[615]||=a(`blockquote`,null,[a(`p`,null,`就这些吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/146.mp3`}),c[616]||=i(),c[617]||=a(`strong`,null,`Janice:`,-1),c[618]||=i(` I should just go on to happier things, okay? Umm, why don’t you tell about your lovely wedding?`,-1),c[619]||=a(`blockquote`,null,[a(`p`,null,`我应该继续做更快乐的事情，好吗？嗯，你为什么不说说你可爱的婚礼？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/147.mp3`}),c[620]||=i(),c[621]||=a(`strong`,null,`Chandler Bing:`,-1),c[622]||=i(` Well actually uh, there was something we wanted to tell you about the wedding. Um, it’s going to be a small ceremony. Uh, tiny! We’re not even sure why we’re having it.`,-1),c[623]||=a(`blockquote`,null,[a(`p`,null,`嗯，事实上，呃，我们想告诉你一些关于婚礼的事情。嗯，这将是一个小型的仪式。嗯，很小！我们甚至不知道为什么会这样。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/148.mp3`}),c[624]||=i(),c[625]||=a(`strong`,null,`Monica Geller:`,-1),c[626]||=i(` It’s actually going to be just family.`,-1),c[627]||=a(`blockquote`,null,[a(`p`,null,`事实上，这只是一个家庭。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/149.mp3`}),c[628]||=i(),c[629]||=a(`strong`,null,`Janice:`,-1),c[630]||=i(` Oh…wait…you two think of me as family?! Oh, I have to ask you something now and be honest; do you want me to sing Careless Whisper or Lady In Red?`,-1),c[631]||=a(`blockquote`,null,[a(`p`,null,`哦…等等…你们两个把我当成家人？！哦，我现在得问你一件事，说实话；你想让我唱《漫不经心的低语》还是《红衣女郎》？`)],-1),c[632]||=a(`hr`,null,null,-1),c[633]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Joey is entering and arguing baseball with Erin. Phoebe and Rachel are already there.`)],-1),c[634]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，乔伊进来和艾琳争论棒球。菲比和瑞秋已经在那里了。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/150.mp3`}),c[635]||=i(),c[636]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[637]||=i(` How can you say that?! The Mets have no closer!`,-1),c[638]||=a(`blockquote`,null,[a(`p`,null,`你怎么能这么说？！大都会队没有更近的距离！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/151.mp3`}),c[639]||=i(),c[640]||=a(`strong`,null,`Erin:`,-1),c[641]||=i(` What about Benitez?`,-1),c[642]||=a(`blockquote`,null,[a(`p`,null,`贝尼特斯呢？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/152.mp3`}),c[643]||=i(),c[644]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[645]||=i(` What about Game 1 of the Series?`,-1),c[646]||=a(`blockquote`,null,[a(`p`,null,`系列赛第一场怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/153.mp3`}),c[647]||=i(),c[648]||=a(`strong`,null,`Erin:`,-1),c[649]||=i(` What about shut up?`,-1),c[650]||=a(`blockquote`,null,[a(`p`,null,`闭嘴怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/154.mp3`}),c[651]||=i(),c[652]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[653]||=i(` You shut up! (To Phoebe and Rachel) I love arguing with her. (To Erin) I’ll be right back.`,-1),c[654]||=a(`blockquote`,null,[a(`p`,null,`你闭嘴！（对菲比和瑞秋）我喜欢和她争论。（对艾琳）我马上回来。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/155.mp3`}),c[655]||=i(),c[656]||=a(`strong`,null,`Erin:`,-1),c[657]||=i(` Okay. (Joey goes to get some coffee and Erin sits down.)`,-1),c[658]||=a(`blockquote`,null,[a(`p`,null,`好的。（乔伊去喝咖啡，艾琳坐了下来。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/156.mp3`}),c[659]||=i(),c[660]||=a(`strong`,null,`Rachel Green:`,-1),c[661]||=i(` So how’s it goin’ with Joey?`,-1),c[662]||=a(`blockquote`,null,[a(`p`,null,`乔伊怎么样了？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/157.mp3`}),c[663]||=i(),c[664]||=a(`strong`,null,`Erin:`,-1),c[665]||=i(` Uh, okay.`,-1),c[666]||=a(`blockquote`,null,[a(`p`,null,`嗯，好的。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/158.mp3`}),c[667]||=i(),c[668]||=a(`strong`,null,`Rachel Green:`,-1),c[669]||=i(` Okay? Wait okay, tell-tell me that you like him, please? I mean tell me that you like him.`,-1),c[670]||=a(`blockquote`,null,[a(`p`,null,`好吗？等等，好吧，告诉我你喜欢他，好吗？我是说告诉我你喜欢他。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/159.mp3`}),c[671]||=i(),c[672]||=a(`strong`,null,`Erin:`,-1),c[673]||=i(` Look, he’s a really great guy and I know that you really want this to work out, but I just don’t see this having a future.`,-1),c[674]||=a(`blockquote`,null,[a(`p`,null,`听着，他是一个很好的人，我知道你真的很想把这件事办好，但我只是觉得这件事没有前途。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/160.mp3`}),c[675]||=i(),c[676]||=a(`strong`,null,`Rachel Green:`,-1),c[677]||=i(` But you said that you liked him! I mean what happened?! Did ya just change your mind?!`,-1),c[678]||=a(`blockquote`,null,[a(`p`,null,`但是你说你喜欢他！我是说发生了什么？！你改变主意了吗？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/161.mp3`}),c[679]||=i(),c[680]||=a(`strong`,null,`Erin:`,-1),c[681]||=i(` Kinda.`,-1),c[682]||=a(`blockquote`,null,[a(`p`,null,`有点。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/162.mp3`}),c[683]||=i(),c[684]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[685]||=i(` Then change it back!`,-1),c[686]||=a(`blockquote`,null,[a(`p`,null,`那就把它换回来！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/163.mp3`}),c[687]||=i(),c[688]||=a(`strong`,null,`Erin:`,-1),c[689]||=i(` I’m sorry I… It’s just there’s no real spark.`,-1),c[690]||=a(`blockquote`,null,[a(`p`,null,`对不起，我……只是没有真正的火花。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/164.mp3`}),c[691]||=i(),c[692]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[693]||=i(` No spark? Didn’t you sleep together?`,-1),c[694]||=a(`blockquote`,null,[a(`p`,null,`没有火花？你们没睡在一起吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/165.mp3`}),c[695]||=i(),c[696]||=a(`strong`,null,`Erin:`,-1),c[697]||=i(` Yeah.`,-1),c[698]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/166.mp3`}),c[699]||=i(),c[700]||=a(`strong`,null,`Rachel Green:`,-1),c[701]||=i(` Ugh, tramp!`,-1),c[702]||=a(`blockquote`,null,[a(`p`,null,`啊，流浪汉！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/167.mp3`}),c[703]||=i(),c[704]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[705]||=i(` Does Joey have any idea?`,-1),c[706]||=a(`blockquote`,null,[a(`p`,null,`乔伊知道吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/168.mp3`}),c[707]||=i(),c[708]||=a(`strong`,null,`Erin:`,-1),c[709]||=i(` I really don’t think he does. And y’know what? Maybe you guys could help clue him in. Y’know, tell him I’m-I’m not interested in a serious relationship or something.`,-1),c[710]||=a(`blockquote`,null,[a(`p`,null,`我真的不认为他会。你知道吗？也许你们可以帮他找到线索。你知道，告诉他我对一段严肃的关系或什么的不感兴趣。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/169.mp3`}),c[711]||=i(),c[712]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[713]||=i(` Yeah, you mean like that you’re kind of a loner.`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`是的，你的意思是你有点孤独。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/170.mp3`}),c[715]||=i(),c[716]||=a(`strong`,null,`Erin:`,-1),c[717]||=i(` Yeah! That would be great!`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,`是啊！那太好了！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/171.mp3`}),c[719]||=i(),c[720]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[721]||=i(` Yeah, and maybe that you’re a real (She says something in Italian, and it doesn’t matter what she said. It’s not important so I don’t need everyone who speaks Italian telling me what she said.)`,-1),c[722]||=a(`blockquote`,null,[a(`p`,null,`是的，也许你是个真正的意大利人（她用意大利语说了些什么，她说什么都没关系。这不重要，所以我不需要每个说意大利语的人都告诉我她说了什么。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/172.mp3`}),c[723]||=i(),c[724]||=a(`strong`,null,`Erin:`,-1),c[725]||=i(` I’m sorry?`,-1),c[726]||=a(`blockquote`,null,[a(`p`,null,`对不起？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/173.mp3`}),c[727]||=i(),c[728]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[729]||=i(` Oh well, I guess Italian isn’t one of the four languages you speak.`,-1),c[730]||=a(`blockquote`,null,[a(`p`,null,`哦，我想意大利语不是你说的四种语言之一。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/174.mp3`}),c[731]||=i(),c[732]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[733]||=i(` (returning) Hey! You wanna go?`,-1),c[734]||=a(`blockquote`,null,[a(`p`,null,`（回头）嘿！你想去吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/175.mp3`}),c[735]||=i(),c[736]||=a(`strong`,null,`Erin:`,-1),c[737]||=i(` Yeah, let’s go.`,-1),c[738]||=a(`blockquote`,null,[a(`p`,null,`是的，我们走吧。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/176.mp3`}),c[739]||=i(),c[740]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[741]||=i(` Okay. See you guys later.`,-1),c[742]||=a(`blockquote`,null,[a(`p`,null,`好的。待会儿见。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/177.mp3`}),c[743]||=i(),c[744]||=a(`strong`,null,`Erin:`,-1),c[745]||=i(` Bye guys.`,-1),c[746]||=a(`blockquote`,null,[a(`p`,null,`再见，伙计们。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/178.mp3`}),c[747]||=i(),c[748]||=a(`strong`,null,`Rachel Green:`,-1),c[749]||=i(` Yeah, see ya.`,-1),c[750]||=a(`blockquote`,null,[a(`p`,null,`是的，再见。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/179.mp3`}),c[751]||=i(),c[752]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[753]||=i(` (whispers to Phoebe and Rachel) Hey, thank you so much. (They both exit.)`,-1),c[754]||=a(`blockquote`,null,[a(`p`,null,`（对菲比和瑞秋小声说）嘿，非常感谢你。（他们都退出了。）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/180.mp3`}),c[755]||=i(),c[756]||=a(`strong`,null,`Rachel Green:`,-1),c[757]||=i(` Wow. Well, I guess it was Cupid who brought her here.`,-1),c[758]||=a(`blockquote`,null,[a(`p`,null,`哇。我猜是丘比特把她带到这里来的。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/181.mp3`}),c[759]||=i(),c[760]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[761]||=i(` No, just a regular old flying dwarf.`,-1),c[762]||=a(`blockquote`,null,[a(`p`,null,`不是，只是一个普通的老矮人。`)],-1),c[763]||=a(`hr`,null,null,-1),c[764]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The library’s Paleontology section, Ross is patrolling as a couple walks up.`)],-1),c[765]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`图书馆的古生物学部分，罗斯正在巡逻，一对夫妇走了过来。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/182.mp3`}),c[766]||=i(),c[767]||=a(`strong`,null,`Ross Geller:`,-1),c[768]||=i(` Yes? Yes?! How can I help you?`,-1),c[769]||=a(`blockquote`,null,[a(`p`,null,`是吗？对我能为您效劳吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/183.mp3`}),c[770]||=i(),c[771]||=a(`strong`,null,`Guy:`,-1),c[772]||=i(` Yeah, we were…we were just looking around.`,-1),c[773]||=a(`blockquote`,null,[a(`p`,null,`是的，我们…我们只是四处看看。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/184.mp3`}),c[774]||=i(),c[775]||=a(`strong`,null,`Ross Geller:`,-1),c[776]||=i(` Oh-oh, you’re-you’re fellow scholars. What exactly were you looking for, hmm? Perhaps, (Grabs a book from the shelf behind him) perhaps Dr. Chester Stock’s musings on the Smiledon Californicus?`,-1),c[777]||=a(`blockquote`,null,[a(`p`,null,`哦，你们是学者。你到底在找什么，嗯？也许，（从他身后的书架上抓起一本书）也许切斯特·斯托克博士对《斯迈尔顿加利福尼亚》的沉思？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/185.mp3`}),c[778]||=i(),c[779]||=a(`strong`,null,`Guy:`,-1),c[780]||=i(` Uhh….`,-1),c[781]||=a(`blockquote`,null,[a(`p`,null,`嗯…。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/186.mp3`}),c[782]||=i(),c[783]||=a(`strong`,null,`Ross Geller:`,-1),c[784]||=i(` Ah… Ah…Get out of here! (The couple retreats. Ross starts looking through the previously mentioned book as a beautiful woman walks into the section.) Uh, meeting someone? Or-or are you just here to brush up on Marion’s views on evolution?`,-1),c[785]||=a(`blockquote`,null,[a(`p`,null,`啊…啊…离开这里！（这对夫妇退后了。罗斯开始翻阅前面提到的书，这时一位美女走进了这一部分。）呃，遇见了什么人？还是你只是来温习马里恩对进化论的看法？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/187.mp3`}),c[786]||=i(),c[787]||=a(`strong`,null,`Woman:`,-1),c[788]||=i(` Uh, actually I find Marion’s views far to progressionist.`,-1),c[789]||=a(`blockquote`,null,[a(`p`,null,`嗯，事实上，我觉得马里恩的观点与进步主义相去甚远。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/188.mp3`}),c[790]||=i(),c[791]||=a(`strong`,null,`Ross Geller:`,-1),c[792]||=i(` I find Marion’s views far to progressionist.`,-1),c[793]||=a(`blockquote`,null,[a(`p`,null,`我觉得马里恩的观点与进步主义者的观点相去甚远。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/189.mp3`}),c[794]||=i(),c[795]||=a(`strong`,null,`Woman:`,-1),c[796]||=i(` I’m sorry, who are you?`,-1),c[797]||=a(`blockquote`,null,[a(`p`,null,`对不起，你是谁？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/190.mp3`}),c[798]||=i(),c[799]||=a(`strong`,null,`Ross Geller:`,-1),c[800]||=i(` I’m a professor here uh, Ross…Geller.`,-1),c[801]||=a(`blockquote`,null,[a(`p`,null,`我是这里的教授，罗斯……盖勒。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/191.mp3`}),c[802]||=i(),c[803]||=a(`strong`,null,`Woman:`,-1),c[804]||=i(` Ross Geller, why do I know that name? It’s uh—Wait! (Grabs his book off of the shelf.) Did you write this?`,-1),c[805]||=a(`blockquote`,null,[a(`p`,null,`罗斯·盖勒，为什么我知道那个名字？是啊，等等！（从书架上抓起他的书）这是你写的吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/192.mp3`}),c[806]||=i(),c[807]||=a(`strong`,null,`Ross Geller:`,-1),c[808]||=i(` Yes! You’re the person who checked out my book?!`,-1),c[809]||=a(`blockquote`,null,[a(`p`,null,`是的！是你借了我的书？！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/193.mp3`}),c[810]||=i(),c[811]||=a(`strong`,null,`Woman:`,-1),c[812]||=i(` Y’know, you look nothing like I would’ve thought. You’re…you’re so young.`,-1),c[813]||=a(`blockquote`,null,[a(`p`,null,`你知道吗，你看起来一点也不像我想象的那样。你…你太年轻了。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/194.mp3`}),c[814]||=i(),c[815]||=a(`strong`,null,`Ross Geller:`,-1),c[816]||=i(` Well I uh, I skipped forth grade.`,-1),c[817]||=a(`blockquote`,null,[a(`p`,null,`我，嗯，我跳过了四年级。`)],-1),c[818]||=a(`p`,null,[i(`⏱ `),a(`em`,null,`Time Lapse, Ross and the woman are now in a state of partial undress and are standing in front of the head librarian with two security guards watching them.`)],-1),c[819]||=a(`blockquote`,null,[a(`p`,null,[i(`⏱ `),a(`em`,null,`随着时间的推移，罗斯和这位女士现在部分脱掉衣服，站在图书馆馆长面前，两名保安在监视他们。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/195.mp3`}),c[820]||=i(),c[821]||=a(`strong`,null,`Ross Geller:`,-1),c[822]||=i(` I am very…very sorry.`,-1),c[823]||=a(`blockquote`,null,[a(`p`,null,`我非常…非常抱歉。`)],-1),c[824]||=a(`hr`,null,null,-1),c[825]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey and Rachel's, Phoebe and Rachel are watching TV as Joey enters.`)],-1),c[826]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊和瑞秋家，菲比和瑞秋正在看电视，乔伊进来了。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/196.mp3`}),c[827]||=i(),c[828]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[829]||=i(` Hey!`,-1),c[830]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/197.mp3`}),c[831]||=i(),c[832]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[833]||=i(` Hey!`,-1),c[834]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/198.mp3`}),c[835]||=i(),c[836]||=a(`strong`,null,`Rachel Green:`,-1),c[837]||=i(` Hi!`,-1),c[838]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/199.mp3`}),c[839]||=i(),c[840]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[841]||=i(` So how was, how was your date?`,-1),c[842]||=a(`blockquote`,null,[a(`p`,null,`你的约会怎么样？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/200.mp3`}),c[843]||=i(),c[844]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[845]||=i(` Oh, it was great! I mean we walked all around the village. We went to this ice cream place, split a milkshake, 70/30 but still… And guess what, I’m thinking about taking her upstate to one of those bed and breakfasts.`,-1),c[846]||=a(`blockquote`,null,[a(`p`,null,`哦，太棒了！我是说我们在村子里走来走去。我们去了一家冰淇淋店，喝了一杯奶昔，70/30，但还是…你猜怎么着，我想带她去北部的一家床上吃早餐。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/201.mp3`}),c[847]||=i(),c[848]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[849]||=i(` Oh really? She said she wants to go away with you?`,-1),c[850]||=a(`blockquote`,null,[a(`p`,null,`哦，真的吗？她说她想和你一起走？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/202.mp3`}),c[851]||=i(),c[852]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[853]||=i(` No-no-no-no-no! It’s a surprise, but it’s gonna be tricky thought because she said she was gonna be pretty busy at work for a while.`,-1),c[854]||=a(`blockquote`,null,[a(`p`,null,`不，不，不，不！这是一个惊喜，但这会是一个棘手的想法，因为她说她会很忙的工作一段时间。`)],-1),c[855]||=a(`p`,null,`Phoebe and **Rachel Green: **Oh no, yeah.`,-1),c[856]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比和`),a(`strong`,null,`瑞秋·格林：`),i(`哦，不，是的。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/203.mp3`}),c[857]||=i(),c[858]||=a(`strong`,null,`Rachel Green:`,-1),c[859]||=i(` Jo-Joey, look honey we-we need to talk okay? Umm, I kinda got the feeling from her today that uh, she’s not lookin’ for a serious relationship.`,-1),c[860]||=a(`blockquote`,null,[a(`p`,null,`乔·乔伊，亲爱的，我们得谈谈，好吗？嗯，我今天从她那里有种感觉，呃，她不是在寻找一段严肃的关系。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/204.mp3`}),c[861]||=i(),c[862]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[863]||=i(` Where are you gettin’ this?`,-1),c[864]||=a(`blockquote`,null,[a(`p`,null,`你从哪儿弄来的？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/205.mp3`}),c[865]||=i(),c[866]||=a(`strong`,null,`Rachel Green:`,-1),c[867]||=i(` Well, she told me. She said she’s kinda a loner.`,-1),c[868]||=a(`blockquote`,null,[a(`p`,null,`嗯，她告诉我的。她说她有点孤独。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/206.mp3`}),c[869]||=i(),c[870]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[871]||=i(` Oh. Oh.`,-1),c[872]||=a(`blockquote`,null,[a(`p`,null,`哦。哦`)],-1),r(p,{src:`/audio/friends/S07/S07E07/207.mp3`}),c[873]||=i(),c[874]||=a(`strong`,null,`Rachel Green:`,-1),c[875]||=i(` Joey…`,-1),c[876]||=a(`blockquote`,null,[a(`p`,null,`乔伊…`)],-1),r(p,{src:`/audio/friends/S07/S07E07/208.mp3`}),c[877]||=i(),c[878]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[879]||=i(` No hey Rach, it’s cool okay? Y’know I’m a loner too! (Heads for his room.) Right?`,-1),c[880]||=a(`blockquote`,null,[a(`p`,null,`不，嘿，瑞秋，很酷，好吗？你知道我也是一个孤独的人！（朝他的房间走去）对吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/209.mp3`}),c[881]||=i(),c[882]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[883]||=i(` Hey Joey, y’know what? You are way to good for her.`,-1),c[884]||=a(`blockquote`,null,[a(`p`,null,`嘿，乔伊，你知道吗？你对她有好处。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/210.mp3`}),c[885]||=i(),c[886]||=a(`strong`,null,`Rachel Green:`,-1),c[887]||=i(` Yeah and honey I promise next time that I will just say good-bye and tell ‘em you’re not looking for a relationship.`,-1),c[888]||=a(`blockquote`,null,[a(`p`,null,`是的，亲爱的，我保证下次我会跟他们说再见，然后告诉他们你不想谈恋爱。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/211.mp3`}),c[889]||=i(),c[890]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[891]||=i(` No! No. Don’t do that, just next time make sure she really likes me.`,-1),c[892]||=a(`blockquote`,null,[a(`p`,null,`不！不，别这样，下次一定要确定她真的喜欢我。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/212.mp3`}),c[893]||=i(),c[894]||=a(`strong`,null,`Rachel Green:`,-1),c[895]||=i(` Well that too. (Joey goes into his room.) Joey?`,-1),c[896]||=a(`blockquote`,null,[a(`p`,null,`那也是。（乔伊走进他的房间）乔伊？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/213.mp3`}),c[897]||=i(),c[898]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[899]||=i(` Yeah?`,-1),c[900]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/214.mp3`}),c[901]||=i(),c[902]||=a(`strong`,null,`Rachel Green:`,-1),c[903]||=i(` Do you want some pancakes?`,-1),c[904]||=a(`blockquote`,null,[a(`p`,null,`你想要些煎饼吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/215.mp3`}),c[905]||=i(),c[906]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[907]||=i(` (coming back out) Finally!`,-1),c[908]||=a(`blockquote`,null,[a(`p`,null,`（回来）终于！`)],-1),c[909]||=a(`hr`,null,null,-1),c[910]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica, Chandler, and Phoebe's, Chandler and Monica are sitting at the kitchen table and are still trying to decide what to do about Janice.`)],-1),c[911]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡、钱德勒和菲比的，钱德勒和莫妮卡坐在厨房的桌子旁，仍在努力决定如何处置珍妮丝。`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/216.mp3`}),c[912]||=i(),c[913]||=a(`strong`,null,`Monica Geller:`,-1),c[914]||=i(` What are we gonna do?`,-1),c[915]||=a(`blockquote`,null,[a(`p`,null,`我们该怎么办？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/217.mp3`}),c[916]||=i(),c[917]||=a(`strong`,null,`Chandler Bing:`,-1),c[918]||=i(` I say we go with Careless Whisper.`,-1),c[919]||=a(`blockquote`,null,[a(`p`,null,`我说我们用粗心的耳语。`)],-1),c[920]||=a(`p`,null,[a(`em`,null,`(There’s a knock on the door and Janice enters.)`)],-1),c[921]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（有人敲门，珍妮丝进来了。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/218.mp3`}),c[922]||=i(),c[923]||=a(`strong`,null,`Janice:`,-1),c[924]||=i(` Chandler?`,-1),c[925]||=a(`blockquote`,null,[a(`p`,null,`钱德勒？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/219.mp3`}),c[926]||=i(),c[927]||=a(`strong`,null,`Chandler Bing:`,-1),c[928]||=i(` (To Monica) Did she see us yet? Did she see us?`,-1),c[929]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）她看见我们了吗？她看见我们了吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/220.mp3`}),c[930]||=i(),c[931]||=a(`strong`,null,`Monica Geller:`,-1),c[932]||=i(` Janice, what umm, what are you doing here?`,-1),c[933]||=a(`blockquote`,null,[a(`p`,null,`珍妮丝，你在这里干什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/221.mp3`}),c[934]||=i(),c[935]||=a(`strong`,null,`Janice:`,-1),c[936]||=i(` Well umm, I thought I was going to go back to my apartment but then I just felt I couldn’t really be alone tonight. (Joey walks into view of the open door behind Janice, sees her, gets a terrified look on his face, and flees in horror.) I was wondering if I could maybe stay here with you, just I really feel that I need to be with family.`,-1),c[937]||=a(`blockquote`,null,[a(`p`,null,`嗯，我以为我要回我的公寓，但后来我觉得今晚我真的不能一个人呆着。（乔伊走进贾妮斯身后敞开的门，看到了她，脸上带着恐惧的表情，恐惧地逃跑了。）我想知道我是否可以和你呆在一起，只是我真的觉得我需要和家人在一起。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/222.mp3`}),c[938]||=i(),c[939]||=a(`strong`,null,`Monica Geller:`,-1),c[940]||=i(` (To Chandler) Our kids are gonna call her Aunt Janice aren’t they?`,-1),c[941]||=a(`blockquote`,null,[a(`p`,null,`（对钱德勒）我们的孩子会叫她珍妮丝阿姨，不是吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/223.mp3`}),c[942]||=i(),c[943]||=a(`strong`,null,`Janice:`,-1),c[944]||=i(` Please, it’s because otherwise I really don’t know what I might do.`,-1),c[945]||=a(`blockquote`,null,[a(`p`,null,`求你了，因为否则我真的不知道我会怎么做。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/224.mp3`}),c[946]||=i(),c[947]||=a(`strong`,null,`Chandler Bing:`,-1),c[948]||=i(` Aren’t you just a tinsy bit curious?`,-1),c[949]||=a(`blockquote`,null,[a(`p`,null,`你不是有点好奇吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/225.mp3`}),c[950]||=i(),c[951]||=a(`strong`,null,`Janice:`,-1),c[952]||=i(` (starting to cry) Do you have any tissues?`,-1),c[953]||=a(`blockquote`,null,[a(`p`,null,`（开始哭）你有纸巾吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/226.mp3`}),c[954]||=i(),c[955]||=a(`strong`,null,`Monica Geller:`,-1),c[956]||=i(` Yeah, in-in-in the bathroom.`,-1),c[957]||=a(`blockquote`,null,[a(`p`,null,`是的，在浴室里。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/227.mp3`}),c[958]||=i(),c[959]||=a(`strong`,null,`Janice:`,-1),c[960]||=i(` Okay! (She runs for the bathroom)`,-1),c[961]||=a(`blockquote`,null,[a(`p`,null,`好的！（她跑向浴室）`)],-1),r(p,{src:`/audio/friends/S07/S07E07/228.mp3`}),c[962]||=i(),c[963]||=a(`strong`,null,`Monica Geller:`,-1),c[964]||=i(` We’ll just…we’ll just let her stay.`,-1),c[965]||=a(`blockquote`,null,[a(`p`,null,`我们就…我们就让她留下来。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/229.mp3`}),c[966]||=i(),c[967]||=a(`strong`,null,`Chandler Bing:`,-1),c[968]||=i(` No-no-no-no, if we let her stay, she will stay forever!`,-1),c[969]||=a(`blockquote`,null,[a(`p`,null,`不不不，如果我们让她留下，她会永远留下来！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/230.mp3`}),c[970]||=i(),c[971]||=a(`strong`,null,`Monica Geller:`,-1),c[972]||=i(` Kinda like your Barca lounger.`,-1),c[973]||=a(`blockquote`,null,[a(`p`,null,`有点像你的巴萨躺椅。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/231.mp3`}),c[974]||=i(),c[975]||=a(`strong`,null,`Chandler Bing:`,-1),c[976]||=i(` Is that what you’re thinking about right now?`,-1),c[977]||=a(`blockquote`,null,[a(`p`,null,`这就是你现在在想的吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/232.mp3`}),c[978]||=i(),c[979]||=a(`strong`,null,`Monica Geller:`,-1),c[980]||=i(` I never stop thinking about it.`,-1),c[981]||=a(`blockquote`,null,[a(`p`,null,`我从未停止过思考。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/233.mp3`}),c[982]||=i(),c[983]||=a(`strong`,null,`Janice:`,-1),c[984]||=i(` Hey you guys, umm do either one of you want to get in there before I take my bath.`,-1),c[985]||=a(`blockquote`,null,[a(`p`,null,`嘿，你们两个，嗯，在我洗澡之前，你们中的任何一个想进去吗。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/234.mp3`}),c[986]||=i(),c[987]||=a(`strong`,null,`Chandler Bing:`,-1),c[988]||=i(` Janice, I’m sorry but umm, you can’t stay here tonight.`,-1),c[989]||=a(`blockquote`,null,[a(`p`,null,`珍妮丝，对不起，但是，你今晚不能呆在这里。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/235.mp3`}),c[990]||=i(),c[991]||=a(`strong`,null,`Janice:`,-1),c[992]||=i(` Why not?`,-1),c[993]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/236.mp3`}),c[994]||=i(),c[995]||=a(`strong`,null,`Chandler Bing:`,-1),c[996]||=i(` Honestly? Our apartment is a hotbed for electromagnetic activity. Now Monica and I have been immunized, but sadly you have not.`,-1),c[997]||=a(`blockquote`,null,[a(`p`,null,`老实说？我们的公寓是电磁活动的温床。现在我和莫妮卡已经接种了疫苗，但遗憾的是你没有。`)],-1),c[998]||=a(`p`,null,[a(`em`,null,`(And she does the laugh.)`)],-1),c[999]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她笑了。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/237.mp3`}),c[1e3]||=i(),c[1001]||=a(`strong`,null,`Janice:`,-1),c[1002]||=i(` Okay, I’m going to need a comforter, but did you have a hypoallergenic one because otherwise I get very nasal. (Makes some weird sound) Do you have a cat? ‘Cause it’s already happening. (Makes a nasal sound) Do you hear that? (She keeps making the nasal sound.)`,-1),c[1003]||=a(`blockquote`,null,[a(`p`,null,`好的，我需要一个被子，但你有没有低过敏性的，因为否则我会很鼻涕。（发出一些奇怪的声音）你有猫吗？”因为这已经发生了。（发出鼻音）你听到了吗？（她不停地发出鼻音。）`)],-1),c[1004]||=a(`p`,null,[a(`em`,null,`(Chandler does the same nasal sound to Chandler.)`)],-1),c[1005]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（钱德勒也对钱德勒发出同样的鼻音。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/238.mp3`}),c[1006]||=i(),c[1007]||=a(`strong`,null,`Monica Geller:`,-1),c[1008]||=i(` Oh my God! Oh my God! You have to go!`,-1),c[1009]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！哦，我的上帝！你必须走！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/239.mp3`}),c[1010]||=i(),c[1011]||=a(`strong`,null,`Janice:`,-1),c[1012]||=i(` Why?`,-1),c[1013]||=a(`blockquote`,null,[a(`p`,null,`为什么？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/240.mp3`}),c[1014]||=i(),c[1015]||=a(`strong`,null,`Monica Geller:`,-1),c[1016]||=i(` Because Chandler still has feelings for you!`,-1),c[1017]||=a(`blockquote`,null,[a(`p`,null,`因为钱德勒对你还有感情！`)],-1),r(p,{src:`/audio/friends/S07/S07E07/241.mp3`}),c[1018]||=i(),c[1019]||=a(`strong`,null,`Janice:`,-1),c[1020]||=i(` He does?`,-1),c[1021]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/242.mp3`}),c[1022]||=i(),c[1023]||=a(`strong`,null,`Chandler Bing:`,-1),c[1024]||=i(` Say again?`,-1),c[1025]||=a(`blockquote`,null,[a(`p`,null,`再说一遍？`)],-1),r(p,{src:`/audio/friends/S07/S07E07/243.mp3`}),c[1026]||=i(),c[1027]||=a(`strong`,null,`Monica Geller:`,-1),c[1028]||=i(` That’s right. That’s right. And that is why you can’t stay here tonight. And probably why you shouldn’t come to the wedding.`,-1),c[1029]||=a(`blockquote`,null,[a(`p`,null,`没错。这是正确的。这就是你今晚不能呆在这里的原因。也许还有你不该来参加婚礼的原因。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/244.mp3`}),c[1030]||=i(),c[1031]||=a(`strong`,null,`Chandler Bing:`,-1),c[1032]||=i(` Feelings, such strong feelings.`,-1),c[1033]||=a(`blockquote`,null,[a(`p`,null,`感觉，如此强烈的感觉。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/245.mp3`}),c[1034]||=i(),c[1035]||=a(`strong`,null,`Monica Geller:`,-1),c[1036]||=i(` I mean, I realize that his feelings may never completely go away, but you can.`,-1),c[1037]||=a(`blockquote`,null,[a(`p`,null,`我的意思是，我知道他的感觉可能永远不会完全消失，但你可以。`)],-1),r(p,{src:`/audio/friends/S07/S07E07/246.mp3`}),c[1038]||=t(` <strong>Janice:</strong> Oh…my Gawd, I-I understand. I-I am so sorry, I’ll go. (Starts for the door.) Good-bye Monica (hugs her), I wish you a lifetime of happiness with him. Chandler, (hugs him) you call me when this goes in the pooper. (Hurries out.)<blockquote><p>哦……我的天啊，我明白了。对不起，我要走了。（开始向门口走去）再见了莫妮卡（拥抱她），我祝你和他一起幸福一生。钱德勒，（拥抱他）当这件事发生时，你给我打电话。（急忙走了出去。）</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>The library’s Paleontology section, Ross is on patrol and stops a security guard through the stack of books.</em></p><blockquote><p>🎬 <em>在图书馆的古生物学部分，罗斯正在巡逻，并阻止一名保安穿过一堆书。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S07/S07E07/247.mp3`}),c[1039]||=i(),c[1040]||=a(`strong`,null,`Ross Geller:`,-1),c[1041]||=i(` (to the guard) Don’t sweat it, I’ve got this section covered. Yeah, in fact I’ve got this little baby (Turns on a mini-flashlight) to shine in people’s eye—(The guard walks away)—Okay, see you later.`,-1),c[1042]||=a(`blockquote`,null,[a(`p`,null,`（对卫兵说）别担心，我已经把这一部分搞定了。是的，事实上我有一个小婴儿（打开一个迷你手电筒）照在人们的眼睛里-（警卫走开）-好的，待会儿见。`)],-1),c[1043]||=a(`p`,null,[a(`em`,null,`(Ross resumes his patrol when his best friend and sister walk up and start to take off their coats, but they stop when they see him.)`)],-1),c[1044]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯继续巡逻，这时他最好的朋友和妹妹走了过来，开始脱外套，但他们一看到他就停了下来。）`)])],-1),r(p,{src:`/audio/friends/S07/S07E07/248.mp3`}),c[1045]||=i(),c[1046]||=a(`strong`,null,`Chandler Bing:`,-1),c[1047]||=i(` I just wanted to show Monica your book. (Ross just glares at him.)`,-1),c[1048]||=a(`blockquote`,null,[a(`p`,null,`我只是想让莫妮卡看看你的书。（罗斯只是瞪了他一眼。）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};